def table(headers,rows):
 t=doc.add_table(rows=1, cols=len(headers)); t.style='Table Grid'
 for i,x in enumerate(headers):t.rows[0].cells[i].text=x
 for row in rows:
  for c,x in zip(t.add_row().cells,row):c.text=str(x)
 for ri,row in enumerate(t.rows):
  for c in row.cells:
   tcPr=c._tc.get_or_add_tcPr(); sh=OxmlElement('w:shd'); sh.set(qn('w:fill'),'E8EDF0' if ri==0 else 'FFFFFF'); tcPr.append(sh)
   mar=OxmlElement('w:tcMar')
   for side in ['top','left','bottom','right']:
    x=OxmlElement('w:'+side);x.set(qn('w:w'),'90');x.set(qn('w:type'),'dxa');mar.append(x)
   tcPr.append(mar)
   borders=OxmlElement('w:tcBorders')
   for side in ['top','left','bottom','right']:
    x=OxmlElement('w:'+side);x.set(qn('w:val'),'single');x.set(qn('w:sz'),'4');x.set(qn('w:color'),'D9D9D9');borders.append(x)
   tcPr.append(borders)
   for para in c.paragraphs:
    para.paragraph_format.space_after=Pt(4);para.paragraph_format.line_spacing=1.1
    for run in para.runs:run.font.size=Pt(10);run.bold=ri==0
  trpr=row._tr.get_or_add_trPr(); trpr.append(OxmlElement('w:cantSplit'))
 t.rows[0]._tr.get_or_add_trPr().append(OxmlElement('w:tblHeader'))
 doc.add_paragraph()
